import { PARAMS, createSimulation, step, setBlocked, setBackupCooling, snapshot } from './model.js';

const $ = id => document.getElementById(id);
const letters = ['A','B','C'];
let counts = [2,2,2];
let sim = createSimulation({counts});
let selected = 1;
let running = false;
let speed = 5;
let latest = snapshot(sim);
let samples = [];
let events = [];
let lastSample = -1;
let lastPaint = 0;
let lastFrame = performance.now();
let worker;
const f = (v,d=1) => Number(v).toFixed(d);
const put = (id,text) => { $(id).textContent = text; };
const timeText = t => `${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`;


